Array.from(document.querySelectorAll('article[data-testid="tweet"]')).slice(0, 5).map(article => {
  const link = article.querySelector('a[href*="/status/"]');
  const author = article.querySelector('[data-testid="User-Name"]')?.textContent || article.querySelector('div[dir="ltr"]')?.textContent || '未知';
  const text = article.querySelector('[data-testid="tweetText"]')?.textContent || article.querySelector('div[lang]')?.textContent || '无文本';
  return { href: link?.href || '无链接', author: author.slice(0, 50), text: text.slice(0, 80) };
})

